import pandas as pd, numpy as np
for f in ['hourly_omni','omni2_mrg1hr','hourly_wind','hourly_ace','hourly_stereo_a','stereo_a_coho1hr','hourly_solar_orbiter','solar_orbiter_coho1hr','hourly_parker_solar_probe','hourly_maven']:
  d=pd.read_csv(f+'.csv',parse_dates=['utc'])
  for col in ['n','B']:
    if col not in d: continue
    ok=d[col].notna().to_numpy()
    w=(d.utc>='2025-11-15')&(d.utc<'2025-12-10')
    xmm=(d.utc>='2025-12-03T12')&(d.utc<'2025-12-04T11')
    runs=[];i=0;n=len(ok)
    while i<n:
      if not ok[i]:
        j=i
        while j<n and not ok[j]: j+=1
        if j-i>=12: runs.append((str(d.utc[i])[:13],str(d.utc[j-1])[:13],j-i))
        i=j
      else: i+=1
    print(f,col,'all %.0f%%'%(100*ok.mean()),'Nov15-Dec10 %.0f%%'%(100*ok[w.to_numpy()].mean()),'XMM %d/%d'%(ok[xmm.to_numpy()].sum(),xmm.sum()),'gaps>=12h:',runs[:12])
"
",
  "description": "Summarize coverage and long gaps per hourly series"
}

